  "inlineSchema": "// Notification Domain Schema - PostgreSQL\n// Includes: notifications, chats, messages\n\ndatasource notiDB {\n  provider = \"postgresql\"\n  url      = env(\"NOTIFICATION_DATABASE_URL\")\n}\n\ngenerator notiClient {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"windows\", \"darwin-arm64\", \"debian-openssl-3.0.x\"]\n  output        = \"../../generated/prisma-notification\"\n}\n\nenum NotificationType {\n  // 기존 유형 / Existing types\n  APPLICATION_ALERT\n  INTERVIEW_UPDATE\n  REMINDER\n  PROMOTION\n  EMAIL_VERIFICATION\n  FINANCIAL_ALERT\n  STATUS_ALERT\n\n  // 기업인증 / Corporate verification (N-01~05)\n  CORP_VERIFY_SUBMITTED\n  CORP_VERIFY_APPROVED\n  CORP_VERIFY_REJECTED\n  CORP_VERIFY_NEW_ADMIN\n  CORP_VERIFY_SLA_ADMIN\n\n  // 개인 온보딩 / Individual onboarding (N-06~11)\n  VISA_VERIFY_APPROVED\n  VISA_VERIFY_REJECTED\n  PROFILE_REMINDER\n  PROFILE_COMPLETE\n  VISA_VERIFY_REMINDER\n  VISA_EXPIRY_WARNING\n\n  // 비자 플래너 / Visa planner (N-12~14)\n  COUPON_ACTIVATED\n  COUPON_EXPIRY_WARNING\n  PLANNER_PAYMENT_CONFIRM\n\n  // 인재풀 / Talent pool (N-15~16)\n  RESUME_VIEWED\n  SCOUT_CONSENT\n\n  // 공고 / Job posting (N-17~20)\n  JOB_ACTIVATED\n  JOB_EXPIRY_WARNING\n  JOB_SUSPENDED\n  JOB_UNSUSPENDED\n\n  // 채용 프로세스 / Hiring process (N-21~27, N-31)\n  NEW_APPLICANT\n  DOCUMENT_PASSED\n  INTERVIEW_CONFIRMED\n  INTERVIEW_REMINDER\n  FINAL_ACCEPTED\n  HIRING_REJECTED\n  APPLICATION_CANCELLED\n  APPLICATION_EXPIRED\n\n  // 공통 / General (N-28~30)\n  SUPPORT_REPLIED\n  PREMIUM_EXPIRY_WARNING\n  PREMIUM_REMOVED\n\n  // 쿠폰 / Coupons (N-32~33)\n  GENERAL_COUPON_ISSUED\n  GENERAL_COUPON_EXPIRY\n}\n\nenum NotificationStatus {\n  PENDING\n  SENDING\n  SENT\n  FAILED\n}\n\nenum NotificationChannel {\n  PLATFORM // 웹/앱 내 알림센터만 / In-app notification center only\n  EMAIL // 이메일만 / Email only\n  PUSH // 앱 푸시만 / App push notification only (legacy alias)\n  BOTH // 이메일+플랫폼 / Email + Platform (legacy alias)\n  ALL // 전 채널 / All channels\n}\n\nmodel Notification {\n  id                 String              @id @default(cuid()) @map(\"id\")\n  userId             String              @map(\"user_id\")\n  email              String?             @notiDB.VarChar(50)\n  subject            String?             @notiDB.VarChar(100)\n  content            String?             @notiDB.VarChar(255)\n  notificationType   NotificationType    @default(REMINDER) @map(\"notification_type\")\n  status             NotificationStatus  @default(PENDING)\n  priority           Int?\n  attempts           Int?\n  maxAttempts        Int?                @map(\"max_attempts\")\n  metadata           String?             @notiDB.Text\n  isRead             Boolean?            @map(\"is_read\")\n  relatedInterviewId String?             @map(\"related_interview_id\")\n  relatedJobPostId   String?             @map(\"related_job_post_id\")\n  createdAt          DateTime            @default(now()) @map(\"created_at\")\n  sendedAt           DateTime?           @map(\"sended_at\")\n  failedAt           DateTime?           @map(\"failed_at\")\n  channel            NotificationChannel @default(BOTH)\n  readAt             DateTime?           @map(\"read_at\")\n  errorMessage       String?             @map(\"error_message\") @notiDB.Text\n\n  // 확장 필드 / Extended fields (Phase H)\n  eventCode    String?   @map(\"event_code\") @notiDB.VarChar(10) // N-01 ~ N-33\n  templateCode String?   @map(\"template_code\") @notiDB.VarChar(40) // WELCOME, CORP_VERIFY_SUBMITTED, etc.\n  channelsSent String?   @map(\"channels_sent\") @notiDB.VarChar(100) // JSON array of actually sent channels / 실제 발송된 채널 JSON\n  scheduledAt  DateTime? @map(\"scheduled_at\") // Cron 예약 발송 시간 / Scheduled send time\n  deepLink     String?   @map(\"deep_link\") @notiDB.VarChar(255) // 알림 클릭 시 이동 URL / Click destination URL\n\n  @@index([userId])\n  @@index([email])\n  @@index([subject])\n  @@index([notificationType])\n  @@index([status])\n  @@index([eventCode])\n  @@index([scheduledAt])\n  @@map(\"notifications\")\n}\n\nmodel Chat {\n  id        String   @id @default(cuid()) @map(\"id\")\n  userOne   String   @map(\"user_one\")\n  userTwo   String   @map(\"user_two\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"chats\")\n}\n\nmodel Message {\n  id         String   @id @default(cuid()) @map(\"id\")\n  senderId   String   @map(\"sender_id\")\n  receiverId String   @map(\"receiver_id\")\n  room       String?  @notiDB.VarChar(255)\n  message    String?  @notiDB.VarChar(255)\n  isSeen     Boolean  @default(false) @map(\"is_seen\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"messages\")\n}\n",
